#!/usr/bin/env bash
# Writes GeoTag/Config/Secrets.swift from environment variables (GitHub Actions secrets).
# Values never get committed. Missing values stay empty and the app explains what's missing.
set -euo pipefail
out="$(dirname "$0")/../GeoTag/Config/Secrets.swift"
esc() { printf '%s' "${1:-}" | sed 's/\\/\\\\/g; s/"/\\"/g'; }
cat > "$out" <<SWIFT
// Generated by ios/ci/write-secrets.sh. Do not commit real values.
enum Secrets {
    static let supabaseURL = "$(esc "${SUPABASE_URL:-}")"
    static let supabaseAnonKey = "$(esc "${SUPABASE_ANON_KEY:-}")"
    static let arcoreAPIKey = "$(esc "${ARCORE_API_KEY:-}")"
    static let arcoreTokenAuth = $( [ "${ARCORE_TOKEN_AUTH:-}" = "true" ] && echo true || echo false )
    static let supportEmail = "$(esc "${SUPPORT_EMAIL:-}")"
    static let siteURL = "$(esc "${SITE_URL:-https://kafka-esq.github.io/geotag}")"
}
SWIFT
echo "wrote $out"
